local resolved = {}
function M:TextureFile(path)
    if type(path) ~= "string" or (issecretvalue and issecretvalue(path)) then
        return path
    end
    local cached = resolved[path]
    if cached then return cached end

    local normalized = path:gsub("/", "\\"):gsub("\\+", "\\")
    local lower = normalized:lower()
    local relative = lower:match("^interface\\addons\\mangui\\assets\\(.+)$")
        or lower:match("^interface\\addons\\mangui\\art\\(.+)$")
    if relative then
        relative = relative:gsub("^legacy\\", "")
        local target = aliases[relative]
        if target then
            cached = assets .. target
            resolved[path] = cached
            return cached
        end
        resolved[path] = path
    end
    return path
end
